import{_ as a,o as i,c as e,ae as n}from"./chunks/framework.BzQXgbNp.js";const m=JSON.parse('{"title":"🛡️ 領地內生物與實體保護規範","description":"","frontmatter":{},"headers":[],"relativePath":"Mc-Claim-Entity-Protection.md","filePath":"Mc-Claim-Entity-Protection.md"}'),o={name:"Mc-Claim-Entity-Protection.md"};function r(s,t,l,c,h,d){return i(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="🛡️-領地內生物與實體保護規範" tabindex="-1">🛡️ 領地內生物與實體保護規範 <a class="header-anchor" href="#🛡️-領地內生物與實體保護規範" aria-label="Permalink to &quot;🛡️ 領地內生物與實體保護規範&quot;">​</a></h1><p>Craft-Core 提供了全面的 <strong>「領地生物與實體保護 (Claim Entity Protection)」</strong>。當您使用 <code>/claim</code> 劃分領地後，領地內的生物與物品實體將獲得完整保護！</p><hr><h2 id="🔒-保護對象與受限行為" tabindex="-1">🔒 保護對象與受限行為 <a class="header-anchor" href="#🔒-保護對象與受限行為" aria-label="Permalink to &quot;🔒 保護對象與受限行為&quot;">​</a></h2><p>非領地成員（未獲得 <code>interact</code> 互動權限或非領地擁有者/OP）在他人領地內將受以下嚴格保護限制：</p><h3 id="_1-⚔️-禁止傷害生物與實體-damage-protection" tabindex="-1">1. ⚔️ 禁止傷害生物與實體 (Damage Protection) <a class="header-anchor" href="#_1-⚔️-禁止傷害生物與實體-damage-protection" aria-label="Permalink to &quot;1. ⚔️ 禁止傷害生物與實體 (Damage Protection)&quot;">​</a></h3><ul><li><strong>受保護生物</strong>：牛、羊、豬、雞、馬、狼、貓、村民、鐵傀儡等所有玩家飼養或繁殖之生物。</li><li><strong>受保護物品實體</strong>：盔甲架 (Armor Stand)、物品展示框 (Item Frame) 等。</li><li><strong>傷害攔截範圍</strong>：包含近戰揮劍、揮拳、遠程弓箭、三叉戟、投擲傷害藥水、煙火與玩家引爆之 TNT。</li><li><em>若無權限嘗試傷害，系統將自動中斷並發出警示：<code>§c[Craft-Core] 領地保護：您無權傷害玩家 領地內的生物/物品！</code></em></li></ul><h3 id="_2-🤝-禁止未授權互動-interaction-protection" tabindex="-1">2. 🤝 禁止未授權互動 (Interaction Protection) <a class="header-anchor" href="#_2-🤝-禁止未授權互動-interaction-protection" aria-label="Permalink to &quot;2. 🤝 禁止未授權互動 (Interaction Protection)&quot;">​</a></h3><ul><li>非領地成員無法在領地內進行未授權的生物互動： <ul><li>✂️ 剪羊毛 / 擠牛奶</li><li>🐴 騎乘馬匹 / 駱駝</li><li>🌾 繁殖生物 / 餵食</li><li>🛍️ 與村民進行交易</li></ul></li></ul><hr><h2 id="⚙️-如何授權好友互動" tabindex="-1">⚙️ 如何授權好友互動 <a class="header-anchor" href="#⚙️-如何授權好友互動" aria-label="Permalink to &quot;⚙️ 如何授權好友互動&quot;">​</a></h2><p>若您希望與好友共建農場或共享村民交易所，可於遊戲內或網頁端授權好友權限：</p><ul><li><strong>遊戲內指令</strong>：<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/claim</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> grant</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">好友玩家</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">名</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> interact</span></span></code></pre></div></li><li><strong>網頁端權限設定</strong>：在 Web Dashboard 的 <a href="./Web-Claims-Management.html">領地保護設定</a> 頁面勾選好友的 <code>Interact (互動)</code> 權限即可！</li></ul>',13)])])}const g=a(o,[["render",r]]);export{m as __pageData,g as default};
